package com.nephh.business;
import com.nephh.common.ApiResponse;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.http.*;
import org.springframework.core.io.FileSystemResource;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.transaction.annotation.Transactional;
import java.nio.file.*;
import java.util.*;
import static com.nephh.business.AccessService.*;

@RestController @RequestMapping("/api/business")
public class ProfileController {
 private final JdbcTemplate db;private final AccessService access;private final PasswordEncoder passwords;private final ObjectMapper json;private final Path files;
 public ProfileController(JdbcTemplate db,AccessService access,PasswordEncoder passwords,ObjectMapper json,@Value("${app.upload-directory:.data/uploads}")String directory){this.db=db;this.access=access;this.passwords=passwords;this.json=json;this.files=Path.of(directory).toAbsolutePath().normalize();}
 @GetMapping("/profile") public ApiResponse<?> profile(@AuthenticationPrincipal Jwt jwt)throws Exception{var a=access.actor(jwt);var row=access.one("select id,username,display_name,role_code,phone,email,preferred_area_id,notification_preferences,idle_minutes,avatar_name from sys_user where id=?",a.id());var result=new LinkedHashMap<String,Object>();result.put("id",a.id());result.put("username",a.username());result.put("displayName",row.get("display_name")==null?a.username():row.get("display_name"));result.put("role",a.role());result.put("phone",Objects.toString(row.get("phone"),""));result.put("email",Objects.toString(row.get("email"),""));result.put("areaId",row.get("preferred_area_id"));result.put("idleMinutes",row.get("idle_minutes"));result.put("avatar",row.get("avatar_name")!=null);result.put("sessionId",jwt.getId());result.put("preferences",row.get("notification_preferences")==null?Map.of("sound",true,"desktop",false,"criticalOnly",false,"quietStart","22:00","quietEnd","07:00"):json.readValue(row.get("notification_preferences").toString(),Map.class));return ApiResponse.ok(result);}
 @PutMapping("/profile") @Transactional public ApiResponse<?> save(@AuthenticationPrincipal Jwt jwt,@RequestBody Map<String,Object>b)throws Exception{var a=access.actor(jwt);String name=text(b,"displayName",100),phone=Objects.toString(b.get("phone"),""),email=Objects.toString(b.get("email"),"");if(phone.length()>32||email.length()>200||(!email.isBlank()&&!email.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$")))bad("手机号或邮箱格式不正确");Long area=b.get("areaId")==null?null:number(b,"areaId");if(area!=null)access.area(a,area);int idle=b.get("idleMinutes")==null?30:(int)number(b,"idleMinutes");if(!Set.of(15,30,60).contains(idle))bad("会话超时可选15、30、60分钟");String preferences=json.writeValueAsString(b.getOrDefault("preferences",Map.of()));if(preferences.length()>2000)bad("通知偏好内容过长");var before=access.one("select display_name,phone,email,idle_minutes from sys_user where id=?",a.id());db.update("update sys_user set display_name=?,phone=?,email=?,preferred_area_id=?,notification_preferences=?,idle_minutes=? where id=?",name,phone,email,area,preferences,idle,a.id());access.audit(a,"UPDATE_PROFILE","USER",a.id(),before,Map.of("displayName",name,"idleMinutes",idle));return ApiResponse.ok(null);}
 @PostMapping("/profile/password") @Transactional public ApiResponse<?> password(@AuthenticationPrincipal Jwt jwt,@RequestBody Map<String,Object>b){var a=access.actor(jwt);String current=Objects.toString(b.get("currentPassword"),""),next=Objects.toString(b.get("newPassword"),"");var user=access.one("select password_hash from sys_user where id=?",a.id());if(!passwords.matches(current,user.get("password_hash").toString()))bad("当前密码不正确");if(next.length()<8||next.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>72||!next.matches(".*[a-zA-Z].*")||!next.matches(".*[0-9].*"))bad("新密码至少8位，包含字母和数字，且不超过72字节");db.update("update sys_user set password_hash=? where id=?",passwords.encode(next),a.id());db.update("update login_session set revoked=true where user_id=? and id<>?",a.id(),Objects.toString(jwt.getId(),""));access.audit(a,"CHANGE_PASSWORD","USER",a.id(),null,"修改密码并下线其他设备");return ApiResponse.ok(null);}
 @GetMapping("/sessions") public ApiResponse<?> sessions(@AuthenticationPrincipal Jwt jwt,jakarta.servlet.http.HttpServletRequest req){var a=access.actor(jwt);var rows=db.queryForList("select id,browser,platform,ip_address,last_seen from login_session where user_id=? and revoked=false and expires_at>CURRENT_TIMESTAMP order by last_seen desc",a.id());var result=new ArrayList<Map<String,Object>>();for(var row:rows){var s=new LinkedHashMap<String,Object>();s.put("id",row.get("id"));s.put("browser",row.get("browser"));s.put("platform",row.get("platform"));s.put("ip",row.get("ip_address"));s.put("location","");s.put("lastSeen",row.get("last_seen"));s.put("current",Objects.equals(row.get("id"),jwt.getId()));result.add(s);}if(jwt.getId()==null)result.add(Map.of("id","legacy","browser","当前浏览器","platform","当前设备","ip",req.getRemoteAddr(),"location","","lastSeen",java.time.Instant.now(),"current",true));return ApiResponse.ok(result);}
 @PostMapping("/sessions/revoke-others") public ApiResponse<?> revokeOthers(@AuthenticationPrincipal Jwt jwt){var a=access.actor(jwt);db.update("update login_session set revoked=true where user_id=? and id<>?",a.id(),Objects.toString(jwt.getId(),""));access.audit(a,"REVOKE_SESSIONS","USER",a.id(),null,"其他设备已下线");return ApiResponse.ok(null);}
 @PostMapping("/sessions/{id}/revoke") public ApiResponse<?> revoke(@AuthenticationPrincipal Jwt jwt,@PathVariable String id){var a=access.actor(jwt);if(!id.equals("legacy"))db.update("update login_session set revoked=true where id=? and user_id=?",id,a.id());access.audit(a,"REVOKE_SESSION","USER",a.id(),null,id);return ApiResponse.ok(null);}
 @PostMapping("/profile/avatar") public ApiResponse<?> avatar(@AuthenticationPrincipal Jwt jwt,@RequestParam MultipartFile file)throws Exception{var a=access.actor(jwt);String type=Objects.toString(file.getContentType(),"");if(file.isEmpty()||file.getSize()>5*1024*1024||!Set.of("image/png","image/jpeg").contains(type))bad("头像须为5MB以内的JPG或PNG");byte[] bytes=file.getBytes();boolean valid=type.equals("image/png")?bytes.length>8&&(bytes[0]&255)==137&&bytes[1]==80&&bytes[2]==78&&bytes[3]==71:bytes.length>3&&(bytes[0]&255)==255&&(bytes[1]&255)==216;if(!valid)bad("图片类型不正确");String name=UUID.randomUUID().toString();Files.createDirectories(files);Files.write(files.resolve(name),bytes);try{db.update("update sys_user set avatar_name=?,avatar_type=? where id=?",name,type,a.id());}catch(Exception e){Files.deleteIfExists(files.resolve(name));throw e;}access.audit(a,"UPDATE_AVATAR","USER",a.id(),null,"更新头像");return ApiResponse.ok(null);}
 @GetMapping("/profile/avatar") public ResponseEntity<?> avatar(@AuthenticationPrincipal Jwt jwt){var a=access.actor(jwt);var row=access.one("select avatar_name,avatar_type from sys_user where id=?",a.id());if(row.get("avatar_name")==null)return ResponseEntity.notFound().build();Path path=files.resolve(row.get("avatar_name").toString()).normalize();if(!path.startsWith(files)||!Files.isRegularFile(path))return ResponseEntity.notFound().build();return ResponseEntity.ok().header("X-Content-Type-Options","nosniff").contentType(MediaType.parseMediaType(row.get("avatar_type").toString())).body(new FileSystemResource(path));}
}
